## My answer to the prompt

A practical `Input` can filter suggestions as the user types, hide the list when there are no matches, and mark invalid values with a red border. Since the prompt doesn’t specify what counts as valid, this version considers a nonempty value valid only if it exactly matches an option (case-insensitively); callers can override that rule with `validate`.

```tsx
import { useEffect, useMemo, useRef, useState } from "react";

type InputProps = {
  options: readonly string[];
  value?: string;
  onChange?: (value: string) => void;
  validate?: (value: string) => boolean;
  maxSuggestions?: number;
};

export function Input({
  options,
  value,
  onChange,
  validate,
  maxSuggestions = 100,
}: InputProps) {
  const [internalValue, setInternalValue] = useState("");
  const [focused, setFocused] = useState(false);
  const [touched, setTouched] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const rootRef = useRef<HTMLDivElement>(null);

  const inputValue = value ?? internalValue;
  const normalizedOptions = useMemo(
    () => options.map((option) => option.toLocaleLowerCase()),
    [options]
  );

  const matches = useMemo(() => {
    const query = inputValue.trim().toLocaleLowerCase();
    if (!query) return [];

    // Limit rendered suggestions so a large result set does not create a huge DOM.
    const result: string[] = [];
    for (const option of options) {
      if (option.toLocaleLowerCase().includes(query)) {
        result.push(option);
        if (result.length >= maxSuggestions) break;
      }
    }
    return result;
  }, [inputValue, options, maxSuggestions]);

  const isValid = validate
